css:
/* General Styles */
body {
  font-family: 'Georgia', 'Times New Roman', serif; 
  line-height: 1.8;
  margin: 0;
  padding: 0;
  background-color: #f5f5f5;
  color: #333;
}

/* Header Section */
header {
  background-color: #052962; 
  color: white;
  padding: 15px 0;
}

header .container {
  max-width: 1200px; /* Centralize content */
  margin: 0 auto; 
  display: flex;
  justify-content: space-between; /* Space between burger menu, logo, and user icon */
  align-items: center;
}

/* Logo Styling */
header .logo {
  font-family: 'Georgia', 'Times New Roman', serif;
  font-size: 2.8em;
  font-weight: bold;
  color: white;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-align: center;
  flex-grow: 1; /* Push logo to the center */
}

/* Burger Menu */
.burger-menu {
  display: flex;
  align-items: center; /* Vertically align the lines and the \"Menu\" text */
  cursor: pointer; /* Pointer cursor */
}

.burger-menu .lines {
  display: flex;
  flex-direction: column;
  justify-content: space-between; /* Space the lines evenly */
  width: 30px; /* Fixed width for the lines container */
  height: 18px; /* Total height for the three lines */
}

.burger-menu .lines div {
  width: 100%; /* Full width for each line */
  height: 3px; /* Thickness of each line */
  background-color: white; /* White lines for visibility */
  border-radius: 2px; /* Rounded edges for a cleaner look */
}

/* 'Menu' Text */
.burger-menu .menu-text {
  color: white;
  font-family: 'Arial', sans-serif;
  font-size: 1.2em;
  font-weight: bold;
  margin-left: 10px; /* Spacing between the burger lines and text */
  line-height: 18px; /* Align with the total height of the burger menu */
}


/* Category Bar */
.category-bar {
  background-color: #052962;
  padding: 10px 0;
  display: flex;
  justify-content: center;
  gap: 20px;
  font-size: 1em;
}

.category-bar .category {
  display: flex;
  align-items: center;
  position: relative;
}

.category-bar .category a {
  text-decoration: none;
  color: white;
  font-weight: bold;
  padding: 5px 10px;
}

.category-bar .category:not(:last-child)::after {
  content: \"\";
  display: block;
  height: 16px;
  width: 1px;
  background-color: white;
  position: absolute;
  right: 0;
}

.category-bar a:hover {
  background-color: #003e80;
  border-radius: 5px;
}

/* Content Layout */
.container.content-layout {
  max-width: 1200px; /* Centralize the main content and sidebar */
  margin: 20px auto;
  display: flex;
  gap: 20px;
}

.main-content {
  flex: 3;
  background-color: white;
  padding: 20px;
  border-radius: 5px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.main-content h1 {
  font-size: 2.5em;
  margin-bottom: 20px;
  color: #052962;
}

.main-content img {
  width: 80%;
  border-radius: 5px;
  margin: 20px 0;
}

.main-content p {
  margin-bottom: 1.5em;
  color: #444;
}

.meta-info {
  font-size: 0.85em;
  color: #666;
  margin-bottom: 10px;
}

/* Sidebar Section */
.sidebar {
  flex: 1;
  background-color: white;
  padding: 20px;
  border-radius: 5px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.sidebar .related-articles {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.sidebar .related-article img {
  width: 100%;
  border-radius: 5px;
  margin-bottom: 10px;
}

.sidebar .related-headline {
  text-decoration: none;
  color: #052962;
  font-weight: bold;
}

.sidebar .related-headline:hover {
  text-decoration: underline;
}

/* Footer Section */
footer {
  max-width: 1200px; /* Ensure footer stays within the container */
  background-color: #333;
  color: white;
  text-align: center;
  padding: 15px 0;
  margin: 20px auto;
  font-size: 0.9em;
}

/* Social Media Bar */
.social-media-bar {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 20px;
}

.social-media-bar a {
  text-decoration: none;
  color: #052962;
  font-weight: bold;
}

.social-media-bar a:hover {
  text-decoration: underline;
}

