/* General Styles */
@font-face {
  font-family: 'DS Walbaumfraktur', serif; 
}

body {
  font-family: 'Times New Roman', Georgia, serif; /* Elegant serif font */
  line-height: 1.8;
  margin: 0;
  padding: 0;
  background-color: #ffffff; /* White background */
}

/* Center Content */
.container {
  max-width: 1200px; /* Maximum width for content */
  margin: 0 auto; /* Center the container horizontally */
  padding: 0px; /* Remove padding for cleaner alignment */
}

/* Header Section */
header {
  background-color: #ffffff; /* White background for header */
  color: black;
  border-bottom: 1px solid #ccc; /* Subtle border for separation */
  padding: 10px 0;
}

header .container {
  display: flex;
  justify-content: space-between; /* Spread elements evenly */
  align-items: center; /* Center elements vertically */
}

/* Burger Menu Icon */
header .burger-menu img {
  width: 32px; /* Icon size */
  height: 32px;
  object-fit: contain;
  cursor: pointer; /* Make it clickable */
}

/* Logo Styling */
header .logo {
  font-family: 'Chomsky', serif; /* Use the locally stored Chomsky font */
  font-size: 4em; /* Increase font size for prominence */
  font-weight: normal; /* Standard weight for Chomsky */
  text-transform: uppercase; /* All caps for professionalism */
  color: #000; /* Black text */
  margin: 0 auto; /* Center the logo */
  text-align: center; /* Align text in the center */
}

/* User/Login Icon */
header .user-icon img {
  width: 32px; /* Standard icon size */
  height: 32px;
  object-fit: contain;
  cursor: pointer; /* Make it clickable */
}

/* Category Navigation Bar */
.category-bar {
  background-color: #f0f0f0; /* Light gray background */
  padding: 10px 0;
  display: flex;
  justify-content: center; /* Center the category links */
  gap: 15px; /* Spacing between categories */
  font-family: 'Georgia', serif; /* Elegant serif font */
}

.category-bar .category a {
  text-decoration: none;
  color: #000; /* Black text */
  font-weight: bold;
  font-size: 1em;
}

.category-bar .category a:hover {
  text-decoration: underline;
}

/* Main Content Layout */
.content-layout {
  display: block; /* No flexbox since sidebar is removed */
}

/* Main Content */
.main-content {
  max-width: 1200px; /* Wider content width now that sidebar is removed */
  margin: 40px auto; /* Center align and add spacing */
  background-color: white;
  padding: 20px;
  border-radius: 5px; /* Slightly rounded corners */
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); /* Subtle shadow */
}

.main-content h1 {
  font-size: 3em; /* Larger headline font size */
  font-weight: bold; /* Emphasized headline */
  color: #333; /* Neutral dark color */
  margin-bottom: 10px;
}

/* Author and Date */
.main-content .meta-info {
  font-size: 1em; /* Readable metadata font size */
  color: #555; /* Muted gray color for metadata */
  margin-bottom: 20px;
  text-align: left; /* Align to the left */
}

/* Main Image */
.main-content img {
  width: 100%; /* Full width of the main content */
  display: block;
  margin: 20px auto; /* Center the image horizontally */
  border-radius: 5px; /* Rounded corners for a modern look */
}

/* Article Text */
.main-content p {
  font-size: 1.1em; /* Slightly larger body text */
  margin-bottom: 1em;
  color: #444; /* Slightly muted text color */
}

/* Footer Section */
footer {
  background-color: #f9f9f9; /* Light gray background */
  color: #666; /* Muted gray text */
  text-align: center; /* Center align text */
  padding: 20px;
  font-size: 0.9em; /* Smaller font size */
  border-top: 1px solid #ccc; /* Subtle top border */
}

