/* General Styles */
body {
  font-family: 'Georgia', 'Times New Roman', serif;
  line-height: 1.8;
  margin: 0;
  padding: 0;
  background-color: #f5f5f5;
  color: #333;
}

/* Header Section */
header {
  background-color: #052962;
  color: white;
  padding: 20px 0; /* Increased depth */
}

header .container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Logo Styling */
header .logo {
  font-family: 'Italiana', sans-serif;
  font-size: 3.5em; /* Larger font size */
  font-weight: normal;
  color: white;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-align: center;
  flex-grow: 1;
}

/* Burger Menu */
.burger-menu {
  display: flex;
  align-items: center;
  cursor: pointer;
  display: none;
}

.burger-menu .lines {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 30px;
  height: 18px;
}

.burger-menu .lines div {
  width: 100%;
  height: 3px;
  background-color: white;
  border-radius: 2px;
}

/* 'Menu' Text */
.burger-menu .menu-text {
  color: white;
  font-family: 'Arial', sans-serif;
  font-size: 1.2em;
  font-weight: bold;
  margin-left: 10px;
}

/* User/Login Icon */
header .user-icon img {
  width: 32px; /* Standard icon size */
  height: 32px;
  object-fit: contain;
  cursor: pointer; /* Make it clickable */
  display: none;
}

/* Category Bar */
.category-bar {
  background-color: #052962;
  padding: 10px 0;
  display: flex;
  justify-content: center;
  gap: 20px;
  font-size: 1.1em; /* Slightly larger font size */
  font-family: 'Italiana', sans-serif;
}

.category-bar .category {
  position: relative;
}

.category-bar .category a {
  text-decoration: none;
  color: white;
  font-weight: bold;
  padding: 5px 10px;
}

.category-bar .category:not(:last-child)::after {
  content: \"\";
  display: block;
  height: 16px;
  width: 1px;
  background-color: white;
  position: absolute;
  right: 0;
}

.category-bar a:hover {
  background-color: #003e80;
  border-radius: 5px;
}

/* Content Layout */
.container.content-layout {
  max-width: 1200px;
  margin: 20px auto;
  display: flex;
  gap: 20px;
  flex-direction: row-reverse; /* Sidebar on the left */
}

/* Main Content */
.main-content {
  flex: 3;
  background-color: white;
  padding: 10px;
  border-radius: 5px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.main-content h1 {
  font-size: 2.5em;
  margin-bottom: 20px;
  color: #052962;
  font-family: 'Italiana', sans-serif;
}

.main-content img {
  width: 90%; /* Image slightly smaller */
  border-radius: 5px;
  margin: 20px 0;
}

.main-content p {
  margin-bottom: 1.5em;
  color: #444;
}

.meta-info {
  font-size: 0.85em;
  color: #666;
  margin-bottom: 10px;
}

/* Sidebar Section */
.sidebar {
  flex: 1;
  background-color: white;
  padding: 20px;
  border-radius: 5px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.sidebar .related-articles {
  display: flex;
  flex-direction: column;
  gap: 10px; /* Reduced spacing */
}

.sidebar .related-article img {
  width: 90%; /* Smaller images */
  border-radius: 5px;
  margin-bottom: 10px;
}

.sidebar .related-headline {
  text-decoration: none;
  color: #052962;
  font-weight: bold;
  font-family: 'Italiana', sans-serif;
}

.sidebar .related-headline:hover {
  text-decoration: underline;
}

/* Footer Section */
footer {
  max-width: 1200px;
  background-color: #333;
  color: white;
  text-align: center;
  padding: 20px;
  margin: 20px auto;
  font-size: 0.9em;
}

/* Social Media Bar */
.social-media-bar {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 20px;
}

.social-media-bar a {
  text-decoration: none;
  color: #052962;
  font-weight: bold;
}

.social-media-bar a:hover {
  text-decoration: underline;
}

"/* General Styles */
body {
